using Microsoft.EntityFrameworkCore;using ProMaxx2.QA.Application.Requirements;using ProMaxx2.QA.Domain.Requirements;
namespace ProMaxx2.QA.Infrastructure.Persistence;
public sealed class RequirementRepository(QaDbContext db):IRequirementRepository
{
 private static RequirementDto Map(Requirement x)=>new(x.RequirementId,x.ProjectId,x.ReleaseId,x.ModuleId,x.RequirementCode,x.Title,x.Description,x.AcceptanceCriteria,x.Priority,x.RiskLevel,x.Source,x.OwnerUserId,x.Status,x.RevisionNo,x.IsInScope,x.CreatedAt);
 public async Task<IReadOnlyList<RequirementDto>>ListAsync(RequirementFilter f,CancellationToken ct){var q=db.Requirements.AsNoTracking().Where(x=>!x.IsDeleted);if(f.ProjectId.HasValue)q=q.Where(x=>x.ProjectId==f.ProjectId);if(f.ReleaseId.HasValue)q=q.Where(x=>x.ReleaseId==f.ReleaseId);if(f.ModuleId.HasValue)q=q.Where(x=>x.ModuleId==f.ModuleId);if(!string.IsNullOrWhiteSpace(f.Status))q=q.Where(x=>x.Status==f.Status);if(!string.IsNullOrWhiteSpace(f.Priority))q=q.Where(x=>x.Priority==f.Priority);if(f.InScope.HasValue)q=q.Where(x=>x.IsInScope==f.InScope);if(!string.IsNullOrWhiteSpace(f.Search))q=q.Where(x=>x.RequirementCode.Contains(f.Search)||x.Title.Contains(f.Search));return await q.OrderBy(x=>x.RequirementCode).Select(x=>new RequirementDto(x.RequirementId,x.ProjectId,x.ReleaseId,x.ModuleId,x.RequirementCode,x.Title,x.Description,x.AcceptanceCriteria,x.Priority,x.RiskLevel,x.Source,x.OwnerUserId,x.Status,x.RevisionNo,x.IsInScope,x.CreatedAt)).ToListAsync(ct);}
 public async Task<RequirementDto?>GetAsync(Guid id,CancellationToken ct){var x=await db.Requirements.AsNoTracking().SingleOrDefaultAsync(x=>x.RequirementId==id&&!x.IsDeleted,ct);return x is null?null:Map(x);}public Task<Requirement?>FindAsync(Guid id,CancellationToken ct)=>db.Requirements.SingleOrDefaultAsync(x=>x.RequirementId==id&&!x.IsDeleted,ct);public Task<bool>CodeExistsAsync(Guid projectId,string code,CancellationToken ct)=>db.Requirements.AnyAsync(x=>x.ProjectId==projectId&&x.RequirementCode==code,ct);public Task AddAsync(Requirement e,CancellationToken ct)=>db.Requirements.AddAsync(e,ct).AsTask();public void AddRevision(RequirementRevision revision)=>db.RequirementRevisions.Add(revision);public async Task<IReadOnlyList<RequirementRevisionDto>>RevisionsAsync(Guid id,CancellationToken ct)=>await db.RequirementRevisions.AsNoTracking().Where(x=>x.RequirementId==id).OrderByDescending(x=>x.RevisionNo).Select(x=>new RequirementRevisionDto(x.RevisionNo,x.Title,x.Description,x.AcceptanceCriteria,x.ChangedBy,x.ChangedAt,x.ChangeReason)).ToListAsync(ct);public Task SaveAsync(CancellationToken ct)=>db.SaveChangesAsync(ct);
}
